sys_ws_operation.operation_script:
(function process(request, response) {
  var STOCK_TABLE = "x_2056099_indust_0_inv_stock";
  var BATCH_TABLE = "x_2056099_indust_0_inv_batch";
  var TXN_TABLE = "x_2056099_indust_0_inv_txn";
  var REQ_TABLE = "x_2056099_indust_0_inv_req";
  var ALERT_TABLE = "x_2056099_indust_0_inv_alert";

  var sysId = request.queryParams.sys_id ? String(request.queryParams.sys_id) : "";

  if (!sysId) {
    response.setBody({ error: "Missing required parameter: sys_id" });
    return;
  }

  // ── Stock record ──
  var stock = null;
  var gr = new GlideRecord(STOCK_TABLE);
  if (gr.get(sysId)) {
    stock = {
      number: gr.getValue("number") || "",
      material: gr.getDisplayValue("material_product") || "",
      materialSysId: gr.getValue("material_product") || "",
      inventoryType: gr.getDisplayValue("inventory_type") || "",
      status: gr.getDisplayValue("status") || "",
      location: gr.getDisplayValue("location") || "",
      locationSysId: gr.getValue("location") || "",
      batchLot: gr.getDisplayValue("batch_lot") || "",
      batchLotSysId: gr.getValue("batch_lot") || "",
      totalQty: gr.getValue("total_quantity") || "0",
      reservedQty: gr.getValue("reserved_quantity") || "0",
      availableQty: gr.getValue("available_quantity") || "0",
      safetyStock: gr.getValue("safety_stock") || "0",
      reorderLevel: gr.getValue("reorder_level") || "0",
      lastUpdated: gr.getDisplayValue("last_updated") || "",
      expiryDate: gr.getDisplayValue("expiry_date") || "",
      active: gr.getValue("active") || "true",
      sysId: sysId
    };
  } else {
    response.setBody({ error: "Stock record not found for sys_id: " + sysId });
    return;
  }

  // ── Batch info ──
  var batch = null;
  if (stock.batchLotSysId) {
    var grBatch = new GlideRecord(BATCH_TABLE);
    if (grBatch.get(stock.batchLotSysId)) {
      batch = {
        batchNumber: grBatch.getValue("batch_number") || "",
        qualityStatus: grBatch.getDisplayValue("quality_status") || "",
        manufacturingDate: grBatch.getDisplayValue("manufacturing_date") || "",
        expiryDate: grBatch.getDisplayValue("expiry_date") || "",
        supplierBatchNumber: grBatch.getValue("supplier_batch_number") || "",
        certificateNumber: grBatch.getValue("certificate_number") || ""
      };
    }
  }

  // ── Recent transactions ──
  var transactions = [];
  var grTxn = new GlideRecord(TXN_TABLE);
  grTxn.addQuery("inventory_stock", sysId);
  grTxn.orderByDesc("transaction_date");
  grTxn.setLimit(10);
  grTxn.query();
  while (grTxn.next()) {
    transactions.push({
      number: grTxn.getValue("number") || "",
      transactionType: grTxn.getDisplayValue("transaction_type") || "",
      quantity: grTxn.getValue("quantity") || "0",
      transactionDate: grTxn.getDisplayValue("transaction_date") || "",
      status: grTxn.getDisplayValue("status") || "",
      sysId: grTxn.getValue("sys_id") || ""
    });
  }

  // ── Related requests ──
  var requests = [];
  var grReq = new GlideRecord(REQ_TABLE);
  grReq.addQuery("related_inventory_stock", sysId);
  grReq.orderByDesc("requested_date");
  grReq.setLimit(10);
  grReq.query();
  while (grReq.next()) {
    requests.push({
      number: grReq.getValue("number") || "",
      requestType: grReq.getDisplayValue("request_type") || "",
      quantityRequested: grReq.getValue("quantity_requested") || "0",
      priority: grReq.getDisplayValue("priority") || "",
      status: grReq.getDisplayValue("status") || "",
      requestedDate: grReq.getDisplayValue("requested_date") || "",
      sysId: grReq.getValue("sys_id") || ""
    });
  }

  // ── Inventory alerts ──
  var alerts = [];
  var grAlert = new GlideRecord(ALERT_TABLE);
  grAlert.addQuery("inventory_stock", sysId);
  grAlert.orderByDesc("alert_date");
  grAlert.setLimit(10);
  grAlert.query();
  while (grAlert.next()) {
    alerts.push({
      number: grAlert.getValue("number") || "",
      alertType: grAlert.getDisplayValue("alert_type") || "",
      severity: grAlert.getDisplayValue("severity") || "",
      alertMessage: grAlert.getValue("alert_message") || "",
      status: grAlert.getDisplayValue("status") || "",
      alertDate: grAlert.getDisplayValue("alert_date") || "",
      sysId: grAlert.getValue("sys_id") || ""
    });
  }

  response.setBody({
    result: {
      stock: stock,
      batch: batch,
      transactions: transactions,
      requests: requests,
      alerts: alerts
    }
  });
})(request, response);
